package agent

import (
	"context"
	"encoding/json"
	"errors"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
	"github.com/jackc/pgx/v5/pgtype"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/garamsh/garam/internal/agent/db"
	"github.com/garamsh/garam/internal/errorx"
	"github.com/garamsh/garam/internal/grn"
)

// PostgresStore implements Store against PostgreSQL. The queries are
// generated by sqlc from queries.sql; the epoch fence is a condition on
// the write itself, not a read followed by a write.
type PostgresStore struct {
	q *db.Queries
}

// Compile-time check that PostgresStore satisfies Store.
var _ Store = (*PostgresStore)(nil)

// NewPostgresStore constructs a Postgres-backed Store.
func NewPostgresStore(pool *pgxpool.Pool) *PostgresStore {
	return &PostgresStore{q: db.New(pool)}
}

// Create persists a new Agent.
func (s *PostgresStore) Create(ctx context.Context, a *Agent) error {
	err := s.q.CreateAgent(ctx, db.CreateAgentParams{
		Grn:               a.grn.String(),
		OrgGrn:            a.orgGRN.String(),
		ProvisioningState: string(a.provisioning),
		RuntimeState:      string(a.runtime),
		CreatedAt:         stamp(a.createdAt),
		UpdatedAt:         stamp(a.updatedAt),
	})
	return classify(err, "create", nil, ErrAgentAlreadyExists)
}

// Get returns the Agent with the given GRN, or ErrAgentNotFound.
func (s *PostgresStore) Get(ctx context.Context, g grn.GRN) (*Agent, error) {
	row, err := s.q.GetAgent(ctx, g.String())
	if err != nil {
		return nil, classify(err, "get", ErrAgentNotFound, nil)
	}
	return rowToAgent(row)
}

// ListByOrg returns the organization's agents.
func (s *PostgresStore) ListByOrg(ctx context.Context, orgGRN grn.GRN) ([]*Agent, error) {
	rows, err := s.q.ListAgentsByOrg(ctx, orgGRN.String())
	if err != nil {
		return nil, classify(err, "list agents", nil, nil)
	}
	agents := make([]*Agent, 0, len(rows))
	for _, row := range rows {
		a, err := rowToAgent(row)
		if err != nil {
			return nil, err
		}
		agents = append(agents, a)
	}
	return agents, nil
}

// Assign binds the agent to an operator at the next epoch. Every call
// raises the epoch, so the pods of the assignment it replaces are
// fenced out whether or not the operator changed.
func (s *PostgresStore) Assign(ctx context.Context, agentGRN, operatorGRN grn.GRN) (*Assignment, error) {
	now := stamp(time.Now().UTC())
	row, err := s.q.AssignAgent(ctx, db.AssignAgentParams{
		AgentGrn:    agentGRN.String(),
		OperatorGrn: operatorGRN.String(),
		CreatedAt:   now,
		UpdatedAt:   now,
	})
	if err != nil {
		return nil, classify(err, "assign", ErrAgentNotFound, nil)
	}
	return rowToAssignment(row)
}

// GetAssignment returns the operator the agent is assigned to and the
// epoch it is assigned at, or ErrAssignmentNotFound.
func (s *PostgresStore) GetAssignment(ctx context.Context, agentGRN grn.GRN) (*Assignment, error) {
	row, err := s.q.GetAgentAssignment(ctx, agentGRN.String())
	if err != nil {
		return nil, classify(err, "get assignment", ErrAssignmentNotFound, nil)
	}
	return rowToAssignment(row)
}

// ListAssignmentsByOrg returns the assignments of the organization's
// agents. An unassigned agent contributes none.
func (s *PostgresStore) ListAssignmentsByOrg(ctx context.Context, orgGRN grn.GRN) ([]*Assignment, error) {
	rows, err := s.q.ListAgentAssignmentsByOrg(ctx, orgGRN.String())
	if err != nil {
		return nil, classify(err, "list assignments", nil, nil)
	}
	assignments := make([]*Assignment, 0, len(rows))
	for _, row := range rows {
		a, err := rowToAssignment(row)
		if err != nil {
			return nil, err
		}
		assignments = append(assignments, a)
	}
	return assignments, nil
}

// ReportProvisioningState records what the operator assigned at epoch
// reports about the agent's pod.
func (s *PostgresStore) ReportProvisioningState(ctx context.Context, agentGRN grn.GRN, epoch int, state ProvisioningState) (*Agent, error) {
	e, err := narrowEpoch(epoch)
	if err != nil {
		return nil, err
	}
	row, err := s.q.ReportAgentProvisioningState(ctx, db.ReportAgentProvisioningStateParams{
		Grn:               agentGRN.String(),
		ProvisioningState: string(state),
		Epoch:             e,
		UpdatedAt:         stamp(time.Now().UTC()),
	})
	if err != nil {
		return nil, s.fenced(ctx, err, "report provisioning state", agentGRN)
	}
	return rowToAgent(row)
}

// ReportRuntimeState records what the agent assigned at epoch reports
// about itself.
func (s *PostgresStore) ReportRuntimeState(ctx context.Context, agentGRN grn.GRN, epoch int, state RuntimeState) (*Agent, error) {
	e, err := narrowEpoch(epoch)
	if err != nil {
		return nil, err
	}
	row, err := s.q.ReportAgentRuntimeState(ctx, db.ReportAgentRuntimeStateParams{
		Grn:          agentGRN.String(),
		RuntimeState: string(state),
		Epoch:        e,
		UpdatedAt:    stamp(time.Now().UTC()),
	})
	if err != nil {
		return nil, s.fenced(ctx, err, "report runtime state", agentGRN)
	}
	return rowToAgent(row)
}

// Define persists a definition. It writes no agent row: what an
// organization says an agent should be and what an operator says
// exists are separate records (ADR-0026).
func (s *PostgresStore) Define(ctx context.Context, d *Definition) error {
	values, err := json.Marshal(d.values)
	if err != nil {
		return errorx.Wrap(err, "agent store: define: values", errorx.KindInternal)
	}
	err = s.q.CreateAgentDefinition(ctx, db.CreateAgentDefinitionParams{
		AgentGrn:    d.agentGRN.String(),
		OrgGrn:      d.orgGRN.String(),
		OperatorGrn: d.operatorGRN.String(),
		AgentValues: values,
		DefinedBy:   d.definedBy.String(),
		CreatedAt:   stamp(d.createdAt),
	})
	return classify(err, "define", nil, nil)
}

// ListDefinitionsByOrg returns the organization's definitions.
func (s *PostgresStore) ListDefinitionsByOrg(ctx context.Context, orgGRN grn.GRN) ([]*Definition, error) {
	rows, err := s.q.ListAgentDefinitionsByOrg(ctx, orgGRN.String())
	if err != nil {
		return nil, classify(err, "list definitions", nil, nil)
	}
	definitions := make([]*Definition, 0, len(rows))
	for _, row := range rows {
		d, err := rowToDefinition(row)
		if err != nil {
			return nil, err
		}
		definitions = append(definitions, d)
	}
	return definitions, nil
}

// narrowEpoch converts a reported epoch to the width of the `epoch`
// column. The module converts to a sqlc parameter without checking;
// here the value decides the fence, and one that truncates onto the
// live epoch would be accepted.
func narrowEpoch(epoch int) (int32, error) {
	e := int32(epoch)
	if int(e) != epoch {
		return 0, ErrStaleEpoch
	}
	return e, nil
}

// fenced says why a state report matched no row: the agent is gone, or
// the epoch is not the one it is assigned at.
func (s *PostgresStore) fenced(ctx context.Context, err error, op string, agentGRN grn.GRN) error {
	if !errors.Is(err, pgx.ErrNoRows) {
		return classify(err, op, nil, nil)
	}
	if _, getErr := s.q.GetAgent(ctx, agentGRN.String()); getErr != nil {
		return classify(getErr, op, ErrAgentNotFound, nil)
	}
	return ErrStaleEpoch
}

// rowToAgent converts a sqlc row into the domain aggregate. A stored
// value that no longer parses is data corruption, hence internal.
func rowToAgent(row db.Agent) (*Agent, error) {
	g, err := grn.Parse(row.Grn)
	if err != nil {
		return nil, errorx.Wrap(err, "agent store: agent grn", errorx.KindInternal)
	}
	orgGRN, err := grn.Parse(row.OrgGrn)
	if err != nil {
		return nil, errorx.Wrap(err, "agent store: agent org grn", errorx.KindInternal)
	}
	if err := validateOwnership(g, orgGRN); err != nil {
		return nil, errorx.Wrap(err, "agent store: stored agent", errorx.KindInternal)
	}
	provisioning, err := ParseProvisioningState(row.ProvisioningState)
	if err != nil {
		return nil, errorx.Wrap(err, "agent store: provisioning state", errorx.KindInternal)
	}
	runtime, err := ParseRuntimeState(row.RuntimeState)
	if err != nil {
		return nil, errorx.Wrap(err, "agent store: runtime state", errorx.KindInternal)
	}
	return &Agent{
		grn:          g,
		orgGRN:       orgGRN,
		provisioning: provisioning,
		runtime:      runtime,
		createdAt:    row.CreatedAt.Time,
		updatedAt:    row.UpdatedAt.Time,
	}, nil
}

// rowToDefinition converts a sqlc row into the domain aggregate. A
// stored value that no longer parses is data corruption, hence
// internal — the values included, which reach the row only through
// [ParseValues].
func rowToDefinition(row db.AgentDefinition) (*Definition, error) {
	agentGRN, err := grn.Parse(row.AgentGrn)
	if err != nil {
		return nil, errorx.Wrap(err, "agent store: definition agent grn", errorx.KindInternal)
	}
	orgGRN, err := grn.Parse(row.OrgGrn)
	if err != nil {
		return nil, errorx.Wrap(err, "agent store: definition org grn", errorx.KindInternal)
	}
	if err := validateOwnership(agentGRN, orgGRN); err != nil {
		return nil, errorx.Wrap(err, "agent store: stored definition", errorx.KindInternal)
	}
	operatorGRN, err := grn.Parse(row.OperatorGrn)
	if err != nil {
		return nil, errorx.Wrap(err, "agent store: definition operator grn", errorx.KindInternal)
	}
	if err := validateOperator(operatorGRN, orgGRN); err != nil {
		return nil, errorx.Wrap(err, "agent store: stored definition", errorx.KindInternal)
	}
	definedBy, err := grn.Parse(row.DefinedBy)
	if err != nil {
		return nil, errorx.Wrap(err, "agent store: definition defined by", errorx.KindInternal)
	}
	var raw map[string]string
	if err := json.Unmarshal(row.AgentValues, &raw); err != nil {
		return nil, errorx.Wrap(err, "agent store: definition values", errorx.KindInternal)
	}
	values, err := ParseValues(raw)
	if err != nil {
		return nil, errorx.Wrap(err, "agent store: definition values", errorx.KindInternal)
	}
	return &Definition{
		agentGRN:    agentGRN,
		orgGRN:      orgGRN,
		operatorGRN: operatorGRN,
		values:      values,
		definedBy:   definedBy,
		createdAt:   row.CreatedAt.Time,
	}, nil
}

func rowToAssignment(row db.AgentAssignment) (*Assignment, error) {
	agentGRN, err := grn.Parse(row.AgentGrn)
	if err != nil {
		return nil, errorx.Wrap(err, "agent store: assignment agent grn", errorx.KindInternal)
	}
	operatorGRN, err := grn.Parse(row.OperatorGrn)
	if err != nil {
		return nil, errorx.Wrap(err, "agent store: assignment operator grn", errorx.KindInternal)
	}
	return &Assignment{
		agentGRN:    agentGRN,
		operatorGRN: operatorGRN,
		epoch:       int(row.Epoch),
		createdAt:   row.CreatedAt.Time,
		updatedAt:   row.UpdatedAt.Time,
	}, nil
}

// classify maps driver errors to errorx kinds. A state outside the
// column's check constraint is a caller mistake, not an outage.
func classify(err error, op string, notFound, conflict error) error {
	if err == nil {
		return nil
	}
	if errors.Is(err, pgx.ErrNoRows) && notFound != nil {
		return notFound
	}
	var pgErr *pgconn.PgError
	if errors.As(err, &pgErr) {
		switch pgErr.Code {
		case "23505":
			if conflict != nil {
				return conflict
			}
			return errorx.Wrap(err, "agent store: "+op, errorx.KindAlreadyExists)
		case "23503":
			if notFound != nil {
				return notFound
			}
			return errorx.Wrap(err, "agent store: "+op+": referenced row missing", errorx.KindNotFound)
		case "23514":
			return errorx.Wrap(err, "agent store: "+op, errorx.KindInvalidArgument)
		}
	}
	return errorx.Wrap(err, "agent store: "+op)
}

// stamp converts a time.Time to a valid pgtype.Timestamptz.
func stamp(t time.Time) pgtype.Timestamptz {
	return pgtype.Timestamptz{Time: t, Valid: true}
}
